// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title ModelBounty
 * @dev Secure native-ETH escrow contract for the ModelBounty reward workflow.
 * Supports bounty escrow funding, authorized reward disbursements, double-spend prevention,
 * and role-based validator access control.
 */
contract ModelBounty is Ownable, ReentrancyGuard {
    struct Bounty {
        string bountyId;
        address creator;
        uint256 escrowedAmount;
        bool active;
    }

    // Mapping from bountyId string to Bounty details
    mapping(string => Bounty) public bounties;

    // Mapping to prevent double payout for the same finding
    mapping(string => bool) public rewardedFindings;

    // Authorized validators
    mapping(address => bool) public isValidator;

    // Events matching ModelBounty specification
    event BountyCreated(
        string bountyId,
        address creator,
        uint256 amount
    );

    event RewardReleased(
        string findingId,
        address recipient,
        uint256 amount
    );

    event ValidatorUpdated(
        address indexed validator,
        bool isAuthorized
    );

    modifier onlyAuthorized() {
        require(msg.sender == owner() || isValidator[msg.sender], "Not authorized");
        _;
    }

    constructor() Ownable(msg.sender) {}

    /**
     * @notice Creates and escrows native ETH for a new bounty.
     * @param bountyId Unique string identifier for the bounty.
     */
    function createBounty(string calldata bountyId) external payable nonReentrant {
        require(bytes(bountyId).length > 0, "Bounty ID cannot be empty");
        require(msg.value > 0, "Bounty escrow must be greater than 0");
        require(bounties[bountyId].creator == address(0), "Bounty ID already exists");

        bounties[bountyId] = Bounty({
            bountyId: bountyId,
            creator: msg.sender,
            escrowedAmount: msg.value,
            active: true
        });

        emit BountyCreated(bountyId, msg.sender, msg.value);
    }

    /**
     * @notice Releases reward to researcher for an approved finding.
     * @dev Protected by checks-effects-interactions pattern and ReentrancyGuard.
     * @param findingId Unique string identifier for the finding.
     * @param recipient Address of the researcher receiving payout.
     * @param amount Payout amount in wei.
     */
    function releaseReward(
        string calldata findingId,
        address payable recipient,
        uint256 amount
    ) external onlyAuthorized nonReentrant {
        require(bytes(findingId).length > 0, "Finding ID cannot be empty");
        require(recipient != address(0), "Invalid recipient address");
        require(amount > 0, "Reward amount must be greater than 0");
        require(!rewardedFindings[findingId], "Finding already rewarded");
        require(address(this).balance >= amount, "Insufficient contract balance");

        // Effects
        rewardedFindings[findingId] = true;

        emit RewardReleased(findingId, recipient, amount);

        // Interaction (safe call)
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "ETH transfer failed");
    }

    /**
     * @notice Updates the authorization status of a validator.
     * @param validator Address of the validator.
     * @param authorized True to authorize, false to revoke.
     */
    function setValidator(address validator, bool authorized) external onlyOwner {
        require(validator != address(0), "Invalid validator address");
        isValidator[validator] = authorized;
        emit ValidatorUpdated(validator, authorized);
    }

    /**
     * @notice Returns bounty details by bountyId.
     */
    function getBounty(string calldata bountyId) external view returns (
        string memory id,
        address creator,
        uint256 escrowedAmount,
        bool active
    ) {
        Bounty memory b = bounties[bountyId];
        return (b.bountyId, b.creator, b.escrowedAmount, b.active);
    }

    /**
     * @notice Checks if a finding has already been rewarded.
     */
    function isFindingRewarded(string calldata findingId) external view returns (bool) {
        return rewardedFindings[findingId];
    }

    /**
     * @notice Returns the current native ETH balance held in the contract.
     */
    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    /**
     * @notice Fallback to accept native ETH directly.
     */
    receive() external payable {}
}

